OA6 = "LE05 OA 06"

CARTA = "Querida Camila: Te escribo desde la casa de la abuela, en el sur. Aquí llueve casi todos los días, pero no me importa porque ayudo a ordenar la bodega y encontramos fotos antiguas. El domingo iremos al mercado a comprar queso. Cuando vuelva te traeré una sorpresa. Un abrazo, Sofía."
HUERTO = "La escuela Los Aromos inauguró ayer su nuevo huerto escolar. Participaron 40 estudiantes de quinto y sexto, que plantaron lechugas, zanahorias y acelgas. La directora dijo que las verduras se usarán en el almuerzo del colegio."
BIO = "Marta Rivas nació en un pueblo de pescadores. A los 12 años ya reparaba redes con su padre. Después estudió ingeniería naval y diseñó botes más seguros para su pueblo, porque varios pescadores habían tenido accidentes en el mar."
RELATO = "Hace muchos años, cuando no había camiones, el trigo se llevaba al molino en carretas tiradas por bueyes. El viaje duraba dos días y las familias acampaban en el camino. Al llegar, el molinero pesaba el trigo y entregaba harina a cambio."
TABLA = "Visitas a la biblioteca en una semana: lunes 24; martes 30; miércoles 18; jueves 30; viernes 42."
MAPA = "Mapa descrito: la plaza está en el centro. La escuela queda al norte de la plaza, la biblioteca al este, el mercado al sur y el hospital al oeste."
TALLERES = "Encuesta «taller favorito» (cada estudiante votó una vez): fútbol 20 votos; lectura 12 votos; dibujo 8 votos."
ABEJA_A = "A. Las abejas producen miel con el néctar de las flores. Una colmena puede tener muchos miles de abejas que trabajan juntas."
ABEJA_B = "B. Las abejas también ayudan a las plantas: al pasar de flor en flor llevan polen, y así muchas plantas pueden dar frutos."
BASURERO = "El municipio instalará 20 nuevos basureros de reciclaje en la plaza. Cada uno costará $50.000 y tendrá tres compartimentos: papel, plástico y metal. Los vecinos podrán usarlos todos los días."

L(OA6, 1,
  "Este cuaderno, lápiz y los textos escritos en esta clase.",
  "Aprenderé a reconocer distintos textos no literarios y a extraer de ellos información explícita e implícita.",
  ["Leo textos informativos.", "Sé qué es una idea principal."],
  ["Los textos no literarios entregan información o cumplen un propósito práctico. Hay cartas, que se escriben a una persona; biografías, que cuentan la vida de alguien; relatos históricos, que cuentan hechos del pasado; noticias, que informan de algo reciente; y libros o artículos informativos, que explican un tema.",
   "La información explícita es la que está escrita directamente en el texto. Por ejemplo, en la carta de Sofía: «El domingo iremos al mercado». La información implícita no está escrita, pero se deduce de pistas. Si Sofía dice «llueve casi todos los días, pero no me importa porque ayudo», se deduce que está contenta con su visita.",
   "Para sacar información explícita, localiza la frase que la dice. Para la implícita, junta pistas del texto y lo que sabes, y comprueba que tu respuesta no contradiga lo escrito. Una buena lectora distingue lo que el texto dice de lo que ella deduce."],
  [("texto no literario", "texto que informa o tiene un fin práctico"), ("información explícita", "la que está escrita directamente en el texto"), ("información implícita", "la que no está escrita, pero se deduce"), ("biografía", "texto que cuenta la vida de una persona")],
  [("Información explícita", f"Lees: «{CARTA}» ¿Dónde está Sofía?", ["Busco dónde se encuentra.", "Dice: «desde la casa de la abuela, en el sur».", "La respuesta está escrita."], "En la casa de la abuela, en el sur"),
   ("Información implícita", "En la misma carta, ¿cómo se siente Sofía en la visita?", ["Dice que llueve, pero no le importa.", "Está ayudando y encontró fotos antiguas.", "Se deduce que está contenta."], "Contenta, aunque no lo dice")],
  [("Responder con una idea propia que contradice el texto.", "Se confunde deducir con inventar.", "Comprueba que tu deducción tenga pistas."), ("Creer que lo implícito no sirve.", "Se cree que solo vale lo escrito.", "Lo implícito completa el sentido del texto.")],
  ([E(CARTA + " En la carta de Sofía, ¿qué comprarán el domingo?", "Queso", "Lo dice: «iremos al mercado a comprar queso»."),
    E(CARTA + " ¿Cómo se llama la persona que recibe la carta?", "Camila", "El saludo dice «Querida Camila»."),
    E("¿Qué texto cuenta la vida de una persona: una biografía o una noticia?", "Una biografía", "Esa es su función.")],
   [E("«Llueve casi todos los días» ¿es información explícita o implícita?", "Explícita", "Está escrita directamente."),
    E(CARTA + " Según la carta, ¿qué encontraron Sofía y su abuela en la bodega?", "Fotos antiguas", "Se dice en la segunda oración."),
    E("¿Qué texto informa de un hecho reciente: una noticia o una biografía?", "Una noticia", "Cuenta lo que pasó hace poco.")],
   [E(f"Lees: «{HUERTO}» ¿Cuántos estudiantes participaron?", "40", "El número está en el texto."),
    E(HUERTO + " En el texto del huerto, ¿qué verduras se plantaron?", "Lechugas, zanahorias y acelgas", "Las nombra la segunda oración."),
    E(HUERTO + " ¿Qué se hará con las verduras, según la directora?", "Se usarán en el almuerzo del colegio", "Lo dice la última oración.")],
   [E("En la carta, «Cuando vuelva te traeré una sorpresa» ¿qué se deduce: que Sofía volverá o que se quedará para siempre?", "Que volverá", "Dice «cuando vuelva»."),
    E(HUERTO + " En el texto del huerto, ¿qué escuela inauguró el huerto?", "Los Aromos", "Lo dice la primera oración.")],
   [E(f"Lees: «{RELATO}» ¿Cuánto duraba el viaje al molino?", "Dos días", "Está escrito en el texto."),
    E("En ese relato, ¿qué se deduce: que las familias viajaban con paradas para dormir o que viajaban de noche?", "Con paradas para dormir", "Acampaban en el camino.")]),
  [E("Una carta de tu curso dice: «Si no puedes venir, avísame mañana». ¿Qué debe hacer quien no puede ir?", "Avisar mañana", "Lo dice la carta.")],
  [E("En un texto no literario, ¿qué es la información explícita?", "La que está escrita directamente", "Se localiza en el texto."),
   E("¿Qué es la información implícita?", "La que se deduce con pistas", "No está escrita palabra por palabra."),
   E("¿Qué hace una biografía?", "Cuenta la vida de alguien", "Su tema es una persona.")],
  (f"Lee: «{BIO}» Escribe: 1) dos datos explícitos; 2) una información implícita que deduces; 3) la pista que te permitió deducirla.", "1) Nació en un pueblo de pescadores; estudió ingeniería naval. 2) Le importaba la seguridad de su pueblo. 3) Diseñó botes más seguros porque hubo accidentes.", ["escribe dos datos explícitos", "deduce una información implícita", "señala la pista"], ["tres respuestas"], ["inventar datos", "no dar pista"], "Pide a otra persona que encuentre tus datos explícitos en el texto."),
  "Lee una carta o noticia y anota un dato explícito y otro implícito.",
  "Escribe una carta de cuatro líneas con un dato implícito y pide a alguien que lo descubra.")

L(OA6, 2,
  "Este cuaderno, lápiz y los textos escritos en esta clase.",
  "Aprenderé a hacer inferencias: deducir información usando pistas del texto y mis conocimientos y experiencias.",
  ["Distingo información explícita e implícita.", "Relaciono lo que leo con lo que sé."],
  ["Una inferencia es una conclusión a la que llegas combinando pistas del texto con lo que sabes. No está escrita, pero tiene apoyo. Si el texto dice que un niño reparaba redes a los 12 años, puedes inferir que trabajaba desde pequeño y conocía el mar.",
   "Para inferir bien, sigue estos pasos: 1) lee la pista, 2) piensa qué sabes del tema, 3) forma una conclusión, 4) comprueba que el texto no la contradiga. Por ejemplo, el huerto: si las verduras se usarán en el almuerzo, puedes inferir que el colegio entrega almuerzo a sus estudiantes.",
   "Hay que evitar las suposiciones sin apoyo. Si dices que la directora es amable, pero el texto no da pistas, estás adivinando. Una buena inferencia comienza con «Se puede inferir que… porque el texto dice…»."],
  [("inferencia", "conclusión que se obtiene con pistas del texto y conocimientos propios"), ("pista", "dato del texto que apoya una conclusión"), ("conclusión", "idea a la que se llega después de pensar"), ("suposición", "idea sin apoyo en el texto")],
  [("Una inferencia con pistas", f"Texto: «{HUERTO}» ¿Qué se infiere de que las verduras se usarán en el almuerzo?", ["Pista: las verduras serán para el almuerzo del colegio.", "Conocimiento: un almuerzo escolar se sirve en la escuela.", "Se infiere que el colegio da almuerzo."], "Que el colegio da almuerzo a sus estudiantes"),
   ("Una suposición sin apoyo", "Alguien dice que la directora es muy estricta. ¿Se puede inferir del texto?", ["Busco pistas sobre cómo es la directora.", "Solo dice que habló del almuerzo.", "No hay pistas: es una suposición."], "No, es una suposición")],
  [("Dar una inferencia sin pista.", "Se adivina.", "Siempre indica la pista del texto."), ("Contradecir el texto.", "Se deja llevar por una idea previa.", "Comprueba tu inferencia con el texto.")],
  ([E("¿Una inferencia está escrita en el texto o se deduce?", "Se deduce", "Se concluye con pistas."),
    E(BIO + " En la biografía de Marta Rivas reparaba redes a los 12 años. ¿Se infiere que trabajaba desde pequeña?", "Sí", "A los 12 años ya trabajaba."),
    E("¿Qué se necesita para que una inferencia sea buena: una pista del texto o solo imaginación?", "Una pista del texto", "Debe tener apoyo.")],
   [E(f"Lees: «{BIO}» ¿Por qué diseñó botes más seguros?", "Porque varios pescadores habían tenido accidentes", "Está escrito en el texto."),
    E("De esa biografía, ¿qué se infiere que le importaba a Marta: la seguridad de su pueblo o ganar mucho dinero?", "La seguridad de su pueblo", "Diseñó botes más seguros por los accidentes."),
    E("¿Dónde nació Marta Rivas?", "En un pueblo de pescadores", "Está escrito en la primera oración.")],
   [E("Un texto dice: «El tren llegó con una hora de atraso porque nevó toda la noche». ¿Qué se infiere del clima?", "Hacía mucho frío", "La nieve ocurre con frío."),
    E("Un texto dice: «Pedro se puso el abrigo y la bufanda para salir». ¿Qué se infiere del día?", "Hacía frío", "Se abriga quien siente frío."),
    E("Un cartel dice: «Cerrado por vacaciones del 1 al 15». ¿Qué se infiere: que reabrirá o que cerró para siempre?", "Que reabrirá", "Hay fechas de vacaciones, luego vuelve.")],
   [E(HUERTO + " Ana dice que la escuela Los Aromos tiene muchos árboles porque se llama así. Beto, que el huerto tiene tierra y agua. ¿Cuál inferencia tiene mejor apoyo?", "La de Beto", "Un huerto necesita tierra y agua."),
    E("Si una inferencia contradice lo que dice el texto, ¿se mantiene o se corrige?", "Se corrige", "Debe coincidir con el texto.")],
   [E(f"Lees: «{RELATO}» ¿Por qué las familias acampaban en el camino?", "Porque el viaje duraba dos días", "No podían llegar el mismo día."),
    E(RELATO + " ¿Qué se infiere de viajar en carretas tiradas por bueyes: que el viaje era lento o que se avanzaba muy rápido?", "Que el viaje era lento", "El texto dice que se tardaban dos días; con bueyes se avanza despacio.")]),
  [E("Ves un cartel: «Hoy no hay clases por reunión de profesores». ¿Qué se infiere: que los estudiantes no asisten hoy o que sí asisten?", "Que no asisten hoy", "No hay clases.")],
  [E("Al leer un artículo, ¿qué es una inferencia?", "Una conclusión con pistas y conocimientos", "Se deduce del texto."),
   E("¿Con qué frase conviene empezar una inferencia?", "«Se puede inferir que… porque el texto dice…»", "Muestra la pista."),
   E("¿Una suposición sin pistas es inferencia?", "No", "Le falta apoyo.")],
  (f"Lee: «{HUERTO}» Escribe dos inferencias, cada una con la pista del texto y el conocimiento que usaste. Luego escribe una suposición que no tendría apoyo.", "1) Se infiere que el huerto requiere cuidados porque las plantas necesitan agua. Pista: «plantaron». 2) Se infiere que el colegio da almuerzo. Pista: «almuerzo del colegio». Suposición sin apoyo: la directora es muy estricta.", ["escribe dos inferencias", "señala pista y conocimiento", "da una suposición sin apoyo"], ["tres respuestas"], ["dar inferencias sin pista", "confundir con suposición"], "Revisa que cada inferencia tenga una pista subrayada."),
  "Lee una noticia y escribe una inferencia con su pista.",
  "Escribe un texto de tres líneas con una información implícita y pide que la infieran.")

L(OA6, 3,
  "Este cuaderno, lápiz y las descripciones de tablas, gráficos, mapas y diagramas escritos en esta clase.",
  "Aprenderé a relacionar la información de imágenes, gráficos, tablas, mapas y diagramas con el texto en el que están.",
  ["Leo tablas simples.", "Sé sumar y restar."],
  ["Muchos textos informativos traen imágenes, gráficos, tablas, mapas o diagramas. Cada uno muestra información de una manera distinta: una tabla ordena datos en filas y columnas; un gráfico de barras compara cantidades; un mapa muestra dónde están las cosas; un diagrama muestra pasos o partes.",
   "Para relacionar el texto con ellos, lee primero el título y las etiquetas. Luego busca qué dato del texto se confirma o se completa con la imagen. A veces la imagen da un dato que el texto no trae. Por ejemplo, un texto dice que la biblioteca tuvo «muchas visitas» y la tabla muestra cuántas fueron cada día.",
   "Las cifras de los gráficos y tablas se pueden usar para calcular: sumar un total, restar para comparar o ver cuál es el mayor. Comprueba siempre que lo que dices coincida con el texto y con la imagen."],
  [("tabla", "organización de datos en filas y columnas"), ("gráfico de barras", "dibujo que compara cantidades con barras"), ("mapa", "dibujo que muestra dónde están los lugares"), ("diagrama", "esquema que muestra partes o pasos")],
  [("Leer una tabla", f"{TABLA} ¿Qué día hubo más visitas?", ["Comparo los números de cada día.", "Viernes tuvo 42.", "Es el mayor."], "El viernes, con 42 visitas"),
   ("Leer un mapa", f"{MAPA} ¿Qué queda al otro lado de la plaza respecto de la escuela?", ["La escuela está al norte.", "Lo opuesto es el sur.", "Al sur está el mercado."], "El mercado")],
  [("Mirar solo el texto y olvidar la imagen.", "Se cree que la imagen es decoración.", "Lee también títulos y etiquetas."), ("Leer mal una cifra.", "Se mira rápido.", "Revisa el dato fila por fila.")],
  ([E(f"{TABLA} ¿Cuántas visitas hubo el lunes?", "24", "Está en la tabla."),
    E("En la misma tabla, ¿qué día tuvo 18 visitas?", "Miércoles", "Es el dato de ese día."),
    E("¿Qué muestra un mapa: dónde están las cosas o los pasos de un proceso?", "Dónde están las cosas", "Ubica los lugares en el espacio.")],
   [E(f"{TABLA} ¿Qué días tuvieron la misma cantidad de visitas?", "Martes y jueves", "Ambos tuvieron 30."),
    E(f"{MAPA} ¿Qué queda al oeste de la plaza?", "El hospital", "Lo dice el mapa."),
    E("¿Qué sirve para comparar cantidades: un gráfico de barras o un mapa?", "Un gráfico de barras", "Las barras muestran cuánto hay de cada cosa.")],
   [arith("Según la tabla de visitas, ¿cuántas visitas hubo en total en la semana? (24, 30, 18, 30, 42)", "24+30+18+30+42", "Se suman los cinco días."),
    arith(f"{TALLERES} ¿Cuántos estudiantes votaron en total?", "20+12+8", "Cada estudiante votó una vez, por lo que se suman los votos."),
    arith("En la tabla de visitas, ¿cuántas visitas más tuvo el viernes que el miércoles? (42 y 18)", "42-18", "Se resta lo menor de lo mayor.")],
   [E("Un texto dice «El taller más popular fue el de fútbol». La encuesta muestra fútbol 20, lectura 12, dibujo 8. ¿El gráfico confirma lo dicho?", "Sí", "Fútbol tiene el mayor número de votos."),
    E("Un texto dice que a la biblioteca fueron «más de 40 personas cada día». Los datos son: lunes 24; martes 30; miércoles 18; jueves 30; viernes 42. ¿Se confirma?", "No", "Solo el viernes pasó de 40.")],
   [arith("En la encuesta de talleres, ¿cuántos votos más tuvo fútbol que dibujo? (20 y 8)", "20-8", "Se resta la menor de la mayor."),
    E("Un diagrama muestra: huevo → oruga → crisálida → mariposa. ¿Qué etapa viene después de la oruga?", "La crisálida", "La flecha indica el orden.")]),
  [E(f"{MAPA} Quieres ir de la biblioteca a la plaza. ¿Hacia qué punto cardinal caminas?", "Hacia el oeste", "La biblioteca está al este de la plaza.")],
  [E("¿Qué ordena la tabla: datos en filas y columnas o dibujos?", "Datos en filas y columnas", "Es su función."),
   E("¿Qué debes leer primero en un gráfico: el título y las etiquetas o solo las barras?", "El título y las etiquetas", "Dicen qué se mide."),
   E("¿Qué puede aportar una imagen que el texto no dice?", "Datos o detalles", "Completa la información.")],
  (f"Lee estos datos: «{TABLA}» y «El texto dice: la biblioteca tuvo una semana muy movida.» Escribe: 1) el total de visitas; 2) qué días estuvieron por encima de 25 visitas; 3) si la tabla apoya o no la frase del texto y por qué.", "1) 144 visitas. 2) Martes, jueves y viernes. 3) La tabla apoya la frase porque hubo 144 visitas, con un máximo de 42 el viernes.", ["calcula el total", "reconoce días con más de 25", "relaciona tabla y texto"], ["tres respuestas"], ["leer mal un dato", "no relacionar con el texto"], "Revisa tus sumas dos veces."),
  "Busca un gráfico o tabla en un libro y escribe una oración que relacione el texto con él.",
  "Crea una tabla de tres filas con datos de tu curso y escribe dos conclusiones.")

L(OA6, 4,
  "Este cuaderno, lápiz y los textos escritos en esta clase.",
  "Aprenderé a interpretar expresiones en lenguaje figurado en textos no literarios y a comparar la información de dos textos sobre un mismo tema.",
  ["Reconozco información explícita e implícita.", "Interpreto lenguaje figurado."],
  ["Los textos no literarios también usan lenguaje figurado, sobre todo las noticias y los artículos. «El equipo es una muralla» no significa que sea de piedra, sino que es muy difícil de vencer. Para interpretar, pregúntate qué quiere decir en ese texto y qué rasgo destaca.",
   "Comparar información es buscar qué dicen dos textos sobre un mismo tema: en qué se parecen y en qué se diferencian. Mira qué datos entrega cada uno, si se contradicen o si se complementan. A veces un texto aporta un dato que el otro no tiene, y juntos explican más.",
   "Para comparar, usa un cuadro con dos columnas, una por texto, y filas con aspectos: tema, datos, ejemplos. Después escribe una conclusión: «El texto A informa sobre…, en cambio el texto B informa sobre…; ambos mencionan…»."],
  [("lenguaje figurado", "uso de palabras con sentido distinto del literal"), ("comparar información", "buscar semejanzas y diferencias entre dos textos"), ("complementar", "completar con algo que faltaba"), ("contradecir", "decir lo opuesto de algo")],
  [("Interpretar una expresión", "Una noticia dice: «El equipo de ajedrez fue una muralla: nadie le ganó». ¿Qué significa «muralla»?", ["Una muralla no se puede pasar.", "El equipo no podía ser vencido.", "Significa que era muy difícil de ganar."], "Que era muy difícil de vencer"),
   ("Comparar dos textos", f"Textos: «{ABEJA_A}» «{ABEJA_B}» ¿Qué aporta cada uno?", ["El A habla de la miel y la colmena.", "El B habla de la ayuda a las plantas.", "Los dos hablan de flores y se complementan."], "A: la miel y la colmena; B: la ayuda a las plantas")],
  [("Interpretar literalmente una expresión figurada.", "Se lee palabra por palabra.", "Pregunta qué quiere decir en el texto."), ("Pensar que dos textos que dicen cosas distintas se contradicen.", "No se ve que pueden complementarse.", "Si hablan de aspectos distintos, se complementan.")],
  ([E("Una noticia dice: «La plaza fue un hervidero de gente». ¿Quiere decir que había agua hirviendo o muchísima gente?", "Muchísima gente", "Es una expresión figurada."),
    E(ABEJA_A + " En el texto A, ¿con qué producen miel las abejas?", "Con el néctar de las flores", "Lo dice la primera oración."),
    E(ABEJA_B + " En el texto B, ¿qué llevan las abejas de flor en flor?", "Polen", "Lo dice el texto.")],
   [E("«El equipo fue una muralla». ¿Qué rasgo destaca: que era alto o que era difícil de vencer?", "Que era difícil de vencer", "Una muralla detiene."),
    E(ABEJA_A + " " + ABEJA_B + " ¿Qué tema comparten los textos A y B?", "Las abejas y las flores", "Ambos hablan de eso."),
    E(ABEJA_A + " " + ABEJA_B + " ¿Qué aporta B que no está en A?", "Que las abejas ayudan a las plantas", "A no habla de eso.")],
   [E("Un artículo dice: «La sequía dejó los campos como un desierto». ¿Qué comparación hace?", "Compara los campos con un desierto", "Usa el nexo «como»."),
    E(ABEJA_A + " " + ABEJA_B + " ¿Qué texto trae el dato de que una colmena puede tener muchos miles de abejas: el A o el B?", "El A", "Está en la segunda oración de A."),
    E("En un cuadro de comparación, ¿qué va en las columnas: un texto en cada una o los aspectos?", "Un texto en cada una", "Así se comparan lado a lado.")],
   [E(ABEJA_A + " " + ABEJA_B + " Un lector dice que A y B se contradicen. ¿Tiene razón?", "No", "Hablan de aspectos distintos y se complementan."),
    E("Un alumno lee «Estoy muerto de cansancio» en una entrevista y concluye que murió. ¿Interpretó bien?", "No", "Es una expresión figurada: está muy cansado.")],
   [E(ABEJA_A + " " + ABEJA_B + " Escribe la semejanza entre A y B.", "Ambos hablan de las abejas y de las flores", "Las dos mencionan flores."),
    E(ABEJA_A + " " + ABEJA_B + " Si juntas A y B, ¿qué dos cosas sabes de las abejas?", "Producen miel y ayudan a las plantas", "Cada texto aporta una.")]),
  [E("En un diario escolar leen: «El patio quedó convertido en una piscina». ¿Qué ocurrió probablemente: llovió mucho o se llenó una piscina?", "Llovió mucho", "Es una exageración figurada.")],
  [E("¿Se encuentra lenguaje figurado solo en los cuentos?", "No", "También en noticias y artículos."),
   E("¿Qué buscas al comparar dos textos?", "Semejanzas y diferencias", "Para ver qué aporta cada uno."),
   E("Dos textos que hablan de aspectos distintos de un tema, ¿se contradicen?", "No, se complementan", "Cada uno aporta datos distintos.")],
  (f"Lee: «{ABEJA_A}» «{ABEJA_B}» Haz un cuadro de dos columnas con dos aspectos de cada texto y escribe una conclusión con «mientras que». Luego inventa una expresión figurada para decir «las abejas trabajan mucho».", "A: miel, colmena. B: polen, plantas. Conclusión: el texto A habla de la miel, mientras que el B habla de cómo ayudan a las plantas. Expresión: «las abejas son pequeñas obreras».", ["cuadro con aspectos", "conclusión con conector", "expresión figurada propia"], ["cuadro", "conclusión", "expresión"], ["no comparar los mismos aspectos", "expresión literal"], "Lee tu expresión a otra persona y pregúntale qué entendió."),
  "Compara dos artículos sobre un tema que te guste en un cuadro.",
  "Busca en una noticia una expresión figurada y explícala.")

L(OA6, 5,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a formular una opinión sobre un aspecto de una lectura y a fundamentarla con información del texto o con mis conocimientos previos.",
  ["Distingo hechos de opiniones.", "Fundamento con ejemplos del texto."],
  ["Un hecho se puede comprobar; una opinión expresa lo que alguien piensa. En un texto informativo, los datos suelen ser hechos, como «cada basurero costará $50.000». Tu opinión sobre si es conveniente es personal, pero debe tener razones.",
   "Para fundamentar tu opinión, usa información del texto o tus conocimientos. Estructura: 1) tu opinión, 2) «porque», 3) un dato del texto o algo que sabes. Por ejemplo: «Creo que es buena idea porque los vecinos podrán separar papel, plástico y metal todos los días». Sin razones, una opinión pierde fuerza.",
   "Opinar no es solo decir «me gusta» o «no me gusta». También puedes ver los dos lados: qué puede ser bueno y qué podría ser un problema. Y puedes cambiar de opinión si encuentras datos nuevos."],
  [("hecho", "algo que se puede comprobar"), ("opinión", "lo que alguien piensa o siente sobre un tema"), ("fundamentar", "apoyar con razones y datos"), ("aspecto", "parte o punto de vista de un tema")],
  [("Opinión con razones", f"Texto: «{BASURERO}» ¿Cómo opinas sobre la medida?", ["Digo mi opinión: es buena.", "Uso «porque».", "Agrego un dato: tres compartimentos para separar los residuos."], "Es una buena medida porque los vecinos podrán separar papel, plástico y metal"),
   ("Distinguir hecho y opinión", "«Cada basurero costará $50.000» y «es demasiado caro». ¿Cuál es hecho?", ["El primero es un dato comprobable.", "El segundo es lo que alguien piensa.", "El hecho es el precio."], "«Cada basurero costará $50.000»")],
  [("Dar una opinión sin razones.", "Se cree que basta decirla.", "Usa «porque» y un dato."), ("Presentar una opinión como si fuera un hecho.", "Se confunde.", "Un hecho se puede comprobar; una opinión, no.")],
  ([E("«El municipio instalará 20 basureros» ¿es un hecho o una opinión?", "Un hecho", "Se puede comprobar."),
    E("«Es una pésima idea» ¿es un hecho o una opinión?", "Una opinión", "Expresa lo que alguien piensa."),
    E("¿Qué palabra ayuda a dar la razón de una opinión?", "Porque", "Introduce la razón.")],
   [E(BASURERO + " Según el texto, ¿cuántos compartimentos tendrá cada basurero?", "Tres", "Papel, plástico y metal."),
    E("¿Cuál es una opinión bien fundamentada: (a) «Me parece bien porque los vecinos podrán reciclar todos los días» o (b) «Me da lo mismo»?", "(a)", "Tiene una razón del texto."),
    E(BASURERO + " ¿Los vecinos podrán usarlos algunos días o todos los días?", "Todos los días", "Lo dice la última oración.")],
   [arith("Si se instalan 20 basureros y cada uno cuesta $50.000, ¿cuántos pesos costarán en total?", "20*50000", "Se multiplica la cantidad por el precio de cada uno."),
    E("Fundamenta con un conocimiento previo la opinión «Reciclar es importante»: ¿qué conocimiento sirve: que el plástico tarda mucho en degradarse o que a mi primo le gusta el fútbol?", "Que el plástico tarda mucho en degradarse", "Es un conocimiento relacionado."),
    E(BASURERO + " Completa: «Creo que es buena idea porque ___».", "Los vecinos podrán separar papel, plástico y metal", "Es un dato del texto.")],
   [E("Ana dice «Es buena idea porque sí». Beto: «Es buena idea porque separa los residuos». ¿Quién fundamenta mejor?", "Beto", "Da una razón."),
    E("Un compañero opina que es mejor poner 10 basureros porque cuestan menos. ¿Su opinión es válida si da esa razón?", "Sí", "Se basa en un dato, aunque se pueda discutir.")],
   [E("Si un vecino dice «El texto no dice dónde se pondrán dentro de la plaza», ¿es una observación válida?", "Sí", "El texto no lo indica."),
    E("¿Cuál es mejor: cambiar de opinión si aparece un dato nuevo o mantenerla sin pensar?", "Cambiar si el dato es convincente", "Una opinión fundamentada puede ajustarse.")]),
  [E("En tu escuela proponen instalar dos nuevos bebederos. ¿Qué razón puedes dar a favor: que el agua es necesaria para los niños o que el color azul es bonito?", "Que el agua es necesaria para los niños", "Es una razón relacionada con el uso.")],
  [E("En Lenguaje: ¿Qué es un hecho?", "Algo que se puede comprobar", "Se puede verificar con datos."),
   E("En Lenguaje: ¿Qué es una opinión?", "Lo que alguien piensa sobre algo", "Es una idea personal."),
   E("¿Qué sigue a «porque» en una opinión?", "Una razón o dato", "Fundamenta lo dicho.")],
  (f"Lee: «{BASURERO}» Escribe tu opinión sobre la medida en tres frases: tu opinión, una razón con un dato del texto y una razón con algo que tú sabes. Anota también un aspecto que te preocupe.", "Opino que es buena medida porque tendrá tres compartimentos para separar los residuos. Además, sé que reciclar ayuda a cuidar el ambiente. Me preocupa quién los vaciará todos los días.", ["opina con claridad", "usa un dato del texto", "usa un conocimiento previo", "señala un aspecto"], ["opinión de tres frases"], ["opinar sin razones", "inventar datos"], "Subraya el dato del texto que usaste."),
  "Lee una noticia y escribe tu opinión con «porque» y un dato del texto.",
  "Escribe dos opiniones opuestas sobre la misma noticia, ambas fundamentadas.")

L(OA6, 6,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a revisar con una lista mis respuestas de comprensión y mi opinión sobre un texto no literario, y a mejorarlas con retroalimentación.",
  ["Extraigo información explícita e implícita.", "Fundamento mi opinión."],
  ["Revisar es releer tu trabajo con preguntas para mejorarlo. Para la comprensión de un texto no literario, puedes preguntar: ¿mis datos están en el texto?, ¿mis inferencias tienen una pista?, ¿relacioné el texto con la tabla o el gráfico?, ¿mi opinión tiene «porque» y un dato?",
   "La retroalimentación es la ayuda que recibes de otra persona o de una lista sobre qué hiciste bien y qué cambiar. Una retroalimentación útil es concreta: «tu opinión no tiene un dato del texto; agrega uno». Decir solo «está mal» no sirve para mejorar.",
   "Después de recibirla, reescribe lo que corresponda y comprueba que el cambio mejoró la respuesta. Guardar la versión anterior permite ver cuánto avanzaste. Mejorar un trabajo es parte normal de aprender."],
  [("revisar", "volver a mirar un trabajo para mejorarlo"), ("retroalimentación", "comentario que dice qué está bien y qué mejorar"), ("lista de revisión", "preguntas para comprobar un trabajo"), ("versión", "forma de un texto en un momento")],
  [("Revisar una opinión", "Borrador: «La biografía de Marta es buena porque sí». ¿Qué retroalimentación le darías?", ["La opinión no tiene razón.", "Falta un dato del texto.", "Que agregue: «porque diseñó botes más seguros»."], "Falta una razón con un dato del texto"),
   ("Mejorar una inferencia", "Borrador: «Marta es rica». ¿Qué falta?", ["No hay pista en el texto.", "El texto dice que nació en un pueblo de pescadores.", "Es una suposición; hay que cambiarla por una inferencia con pista."], "Una pista del texto")],
  [("Recibir una retroalimentación y no cambiar nada.", "Se cree que el trabajo ya está bien.", "Cambia lo que se pidió y comprueba."), ("Dar una retroalimentación vaga.", "Se dice solo «mal».", "Señala qué cambiar y cómo.")],
  ([E("Al revisar tu comprensión de un texto, ¿qué es la retroalimentación?", "Un comentario sobre qué mejorar", "Ayuda a corregir."),
    E("Una retroalimentación útil, ¿es concreta o vaga?", "Concreta", "Dice qué cambiar."),
    E("¿Qué debe tener una opinión: una razón con un dato o solo «me gusta»?", "Una razón con un dato", "Así queda fundamentada.")],
   [E(f"Lees: «{BIO}» Un borrador dice «Marta nació en una gran ciudad». ¿Contradice el texto?", "Sí", "El texto dice que nació en un pueblo de pescadores."),
    E(BIO + " Otro borrador dice «Marta se preocupó por la seguridad de su pueblo porque hubo accidentes». ¿Tiene pista del texto?", "Sí", "Menciona los accidentes."),
    E("¿Qué sirve para revisar: una lista de revisión o adivinar?", "Una lista de revisión", "Ordena las preguntas.")],
   [E("Borrador: «Los estudiantes aprenden en el huerto». ¿Qué retroalimentación conviene: agregar un dato del texto o borrar todo?", "Agregar un dato del texto", "Falta apoyar la idea."),
    E("Borrador de una inferencia: «Marta es famosa». ¿Falta pista o está bien?", "Falta pista", "El texto no lo sugiere."),
    E(TABLA + " Borrador: «Según la tabla, el viernes hubo 42 visitas». ¿Está bien relacionado con los datos?", "Sí", "Coincide con la tabla.")],
   [E("Ana mejoró su opinión agregando un dato del texto. Beto no cambió nada. ¿Quién aprovechó la retroalimentación?", "Ana", "Hizo el cambio pedido."),
    E("¿Por qué guardar la versión anterior: para ver cuánto mejoraste o para no revisar?", "Para ver cuánto mejoraste", "Permite comparar ambas versiones.")],
   [E("Un borrador dice «Marta Rivas fue ingeniera naval porque estudió esa carrera». ¿Qué parte es el dato del texto?", "Estudió ingeniería naval", "Es lo que dice el texto."),
    E("¿Cuál mejora «Fue una buena persona»: (a) «Fue una buena persona, la mejor» o (b) «Fue una buena persona porque diseñó botes más seguros para su pueblo»?", "(b)", "Añade una razón con un dato del texto.")]),
  [E("Tu profesora te devuelve un trabajo con el comentario «Agrega un dato del texto en tu opinión». ¿Qué haces?", "Releo el texto, elijo un dato y lo agrego", "Eso responde al comentario.")],
  [E("¿Qué se hace después de recibir retroalimentación?", "Se corrige y se comprueba", "Se aplica el comentario."),
   E("¿Qué permite la lista de revisión?", "Comprobar mi trabajo con preguntas", "Ayuda a mejorarlo."),
   E("¿Es normal mejorar un trabajo varias veces?", "Sí", "Aprender incluye corregir.")],
  (f"Lee: «{BIO}» Escribe una opinión sobre Marta Rivas. Luego revisa con esta lista: ¿tiene «porque»?, ¿tiene un dato del texto?, ¿evita inventar? Pide a otra persona que te dé una retroalimentación concreta y reescribe tu opinión.", "Primera versión: Marta fue admirable. Retroalimentación: agrega un dato. Versión final: Marta fue admirable porque diseñó botes más seguros tras los accidentes de pescadores.", ["escribe una opinión", "revisa con la lista", "reescribe con retroalimentación"], ["dos versiones"], ["no cambiar nada", "retroalimentación vaga"], "Compara las dos versiones y explica qué mejoró."),
  "Revisa con la lista una respuesta que hayas escrito en otra asignatura.",
  "Escribe una retroalimentación concreta para este borrador: «El huerto es bueno».")
